"use client";

import React, { useEffect, useState, useCallback } from "react";
import { useRouter } from "next/navigation";
import { ShieldAlert, ArrowLeft, Search, Map, Train, AlertTriangle, BarChart3, Sparkles, Check, X, Loader2, ArrowRight, RefreshCw } from "lucide-react";
import Link from "next/link";
import { fetchWithAuth } from "@/lib/fetchWithAuth";
import { API_HOST } from "@/lib/api";

const API = API_HOST;

function getAuthHeaders(): Record<string, string> {
  try {
    const token = localStorage.getItem("accessToken") || "";
    const user = JSON.parse(localStorage.getItem("user") || "{}");
    const headers: Record<string, string> = {};
    if (token) headers["Authorization"] = `Bearer ${token}`;
    if (user.id) headers["x-user-id"] = user.id;
    return headers;
  } catch {
    return {};
  }
}

type TabType = "queries" | "routes" | "stations" | "trains" | "gpt" | "analytics";
type RouteFilterType = "all" | "current_miss" | "resolved" | "historical" | "stale" | "search";

export default function SelfLearningAdminPanel() {
  const [activeTab, setActiveTab] = useState<TabType>("queries");
  const [data, setData] = useState<any[]>([]);
  const [gptFilter, setGptFilter] = useState<"all" | "pending" | "approved" | "rejected">("all");
  const [routeFilter, setRouteFilter] = useState<RouteFilterType>("all");
  const [analytics, setAnalytics] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [actioningId, setActioningId] = useState<string | null>(null);
  const [revalidatingId, setRevalidatingId] = useState<string | null>(null);
  const [isAdmin, setIsAdmin] = useState<boolean | null>(null);

  const verifyAdminAuth = useCallback(async () => {
    try {
      const userStr = localStorage.getItem("user");
      if (!userStr) {
        setIsAdmin(false);
        return;
      }
      const { ensureAccessToken } = await import('@/lib/sessionBootstrap');
      await ensureAccessToken();

      const user = JSON.parse(userStr);
      if (!user.isAdmin) {
        setIsAdmin(false);
        return;
      }
      setIsAdmin(true);
      fetchTab(activeTab);
      fetchAnalytics();
    } catch {
      setIsAdmin(false);
    }
  }, [activeTab]);

  const fetchTab = async (tab: TabType) => {
    if (tab === "analytics") {
      fetchAnalytics();
      return;
    }

    try {
      setLoading(true);
      let tableName = "missing_queries";
      if (tab === "routes") tableName = "missing_routes";
      else if (tab === "stations") tableName = "missing_stations";
      else if (tab === "trains") tableName = "missing_trains";
      else if (tab === "gpt") tableName = "missing_queries"; // GPT suggestions are stored inside missing_queries

      const res = await fetchWithAuth(`${API}/api/admin/self-learning/data?table=${tableName}`, {
        headers: getAuthHeaders()
      });
      const json = await res.json();
      if (json.success) {
        let list = json.data || [];
        if (tab === "gpt") {
          // Filter to only items with a GPT suggestion
          list = list.filter((item: any) => item.gpt_suggestion);
        }
        setData(list);
      }
    } catch (err) {
      console.error("Failed to fetch self-learning data", err);
    } finally {
      setLoading(false);
    }
  };

  const fetchAnalytics = async () => {
    try {
      const res = await fetchWithAuth(`${API}/api/admin/self-learning/analytics`, {
        headers: getAuthHeaders()
      });
      const json = await res.json();
      if (json.success) {
        setAnalytics(json.data);
      }
    } catch (err) {
      console.error("Failed to fetch analytics", err);
    }
  };

  useEffect(() => {
    verifyAdminAuth();
  }, [verifyAdminAuth]);

  const handleAction = async (tab: TabType, id: string, action: "approve" | "reject") => {
    setActioningId(id);
    try {
      let tableName = "missing_queries";
      if (tab === "routes") tableName = "missing_routes";
      else if (tab === "stations") tableName = "missing_stations";
      else if (tab === "trains") tableName = "missing_trains";
      else if (tab === "gpt") tableName = "missing_queries";

      const res = await fetchWithAuth(`${API}/api/admin/self-learning/${action}`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify({ table: tableName, id })
      });
      const json = await res.json();
      if (json.success) {
        // Refresh active tab and analytics
        fetchTab(activeTab);
        fetchAnalytics();
      } else {
        alert(json.error || `Failed to ${action} record`);
      }
    } catch (err) {
      console.error(err);
      alert(`Error during ${action}`);
    } finally {
      setActioningId(null);
    }
  };

  const handleRevalidate = async (id: string, source: string, destination: string, date?: string) => {
    setRevalidatingId(id);
    try {
      const res = await fetchWithAuth(`${API}/api/admin/self-learning/revalidate-split`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify({ id, source, destination, date })
      });
      const json = await res.json();
      if (json.success) {
        fetchTab(activeTab);
        fetchAnalytics();
      } else {
        alert(json.error || "Failed to revalidate split route");
      }
    } catch (err: any) {
      console.error(err);
      alert("Error during split revalidation: " + (err.message || err));
    } finally {
      setRevalidatingId(null);
    }
  };

  const filteredData = activeTab === "gpt" && gptFilter !== "all"
    ? data.filter((item: any) => item.status === gptFilter)
    : activeTab === "routes" && routeFilter !== "all"
    ? data.filter((item: any) => {
        if (routeFilter === "current_miss") return item.current_state === "CURRENT_MISS";
        if (routeFilter === "resolved") return item.current_state === "RESOLVED";
        if (routeFilter === "historical") return item.current_state === "HISTORICAL_MISS" || !item.current_state;
        if (routeFilter === "stale") return item.current_state === "STALE";
        if (routeFilter === "search") return item.category === "SEARCH_ROUTE_MISS";
        return true;
      })
    : data;

  if (isAdmin === false) {
    return <div className="p-8 text-center text-red-500 font-sans">Access Denied</div>;
  }

  return (
    <div className="min-h-screen bg-[#080b11] text-gray-200 font-sans p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
          <div className="flex items-center gap-4">
            <Link href="/admin" className="p-2 bg-[#121824] hover:bg-[#1a2335] border border-gray-800 rounded-xl transition">
              <ArrowLeft size={20} />
            </Link>
            <div>
              <h1 className="text-2xl font-bold flex items-center gap-2 text-white">
                <Sparkles className="text-indigo-400 animate-pulse" size={24} /> Self Learning Engine Cockpit
              </h1>
              <p className="text-gray-400 text-sm">Review search failure telemetry and approve GPT transit suggestions</p>
            </div>
          </div>

          {/* Quick Stats Banner */}
          {analytics?.counts && (
            <div className="flex gap-4 bg-[#101622] border border-gray-800/80 rounded-xl px-4 py-2.5 text-xs">
              <div className="flex flex-col">
                <span className="text-gray-500 font-medium">Pending Queries</span>
                <span className="text-indigo-400 font-bold text-sm">{analytics.counts.missing_queries}</span>
              </div>
              <div className="w-[1px] bg-gray-800" />
              <div className="flex flex-col">
                <span className="text-gray-500 font-medium">Pending Routes</span>
                <span className="text-pink-400 font-bold text-sm">{analytics.counts.missing_routes}</span>
              </div>
              <div className="w-[1px] bg-gray-800" />
              <div className="flex flex-col">
                <span className="text-gray-500 font-medium">Learned Memory</span>
                <span className="text-emerald-400 font-bold text-sm">{analytics.counts.route_memory}</span>
              </div>
            </div>
          )}
        </div>

        {/* Navigation Tabs */}
        <div className="flex gap-2 border-b border-gray-800/80 pb-px mb-6 overflow-x-auto">
          {[
            { id: "queries", label: "Missing Searches", icon: Search, count: analytics?.counts?.missing_queries },
            { id: "routes", label: "Missing Routes", icon: Map, count: analytics?.counts?.missing_routes },
            { id: "stations", label: "Missing Stations", icon: AlertTriangle, count: analytics?.counts?.missing_stations },
            { id: "trains", label: "Missing Trains", icon: Train, count: analytics?.counts?.missing_trains },
            { id: "gpt", label: "GPT Suggestions", icon: Sparkles, count: data.filter(d => d.gpt_suggestion).length },
            { id: "analytics", label: "Telemetry & Aggregates", icon: BarChart3 },
          ].map((tab) => {
            const Icon = tab.icon;
            const active = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => {
                  setActiveTab(tab.id as TabType);
                  fetchTab(tab.id as TabType);
                }}
                className={`flex items-center gap-2 px-4 py-2.5 font-medium text-xs rounded-t-xl transition duration-150 border-t border-x ${
                  active
                    ? "bg-[#121824] text-indigo-400 border-gray-800/80 border-b-[#121824] font-semibold"
                    : "text-gray-400 border-transparent hover:text-gray-200 hover:bg-[#0c1017]"
                }`}
              >
                <Icon size={14} />
                <span>{tab.label}</span>
                {tab.count !== undefined && tab.count > 0 && (
                  <span className="px-1.5 py-0.5 bg-gray-800 text-gray-300 rounded-full text-[10px]">
                    {tab.count}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        {/* Tab Contents */}
        <div className="bg-[#0e131d] border border-gray-800/80 rounded-2xl p-4 md:p-6 shadow-xl">
          {loading ? (
            <div className="flex items-center justify-center p-16 text-indigo-400 gap-2">
              <Loader2 className="animate-spin" size={20} />
              <span className="text-sm">Loading telemetry data...</span>
            </div>
          ) : activeTab === "analytics" ? (
            /* ANALYTICS DASHBOARD */
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="bg-[#121824] border border-gray-800/80 rounded-xl p-4">
                  <span className="text-gray-500 text-xs font-semibold uppercase tracking-wider">Missing Station Queries</span>
                  <div className="text-2xl font-bold text-white mt-1">{analytics?.counts?.missing_stations || 0}</div>
                  <span className="text-xs text-gray-400 mt-1 block">Unresolved input text occurrences</span>
                </div>
                <div className="bg-[#121824] border border-gray-800/80 rounded-xl p-4">
                  <span className="text-gray-500 text-xs font-semibold uppercase tracking-wider">Missing Routes Recorded</span>
                  <div className="text-2xl font-bold text-white mt-1">{analytics?.counts?.missing_routes || 0}</div>
                  <span className="text-xs text-gray-400 mt-1 block">Routes with 0 valid splits</span>
                </div>
                <div className="bg-[#121824] border border-gray-800/80 rounded-xl p-4">
                  <span className="text-gray-500 text-xs font-semibold uppercase tracking-wider">Learned Route Memory</span>
                  <div className="text-2xl font-bold text-emerald-400 mt-1">{analytics?.counts?.route_memory || 0}</div>
                  <span className="text-xs text-gray-400 mt-1 block">Cached successful combinations</span>
                </div>
                <div className="bg-[#121824] border border-gray-800/80 rounded-xl p-4">
                  <span className="text-gray-500 text-xs font-semibold uppercase tracking-wider">Verified Routes</span>
                  <div className="text-2xl font-bold text-indigo-400 mt-1">{analytics?.counts?.verified_routes || 0}</div>
                  <span className="text-xs text-gray-400 mt-1 block">High-confidence curated links</span>
                </div>
              </div>

              {/* Aggregation Insights */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pt-4">
                {/* Top Missing Searches */}
                <div className="bg-[#121824] border border-gray-800/80 rounded-xl p-5">
                  <h3 className="text-sm font-semibold text-white mb-3">Top Missing Searches</h3>
                  <div className="space-y-3.5">
                    {(!analytics?.topQueries || analytics.topQueries.length === 0) ? (
                      <p className="text-xs text-gray-400 text-center py-4">No query logs available</p>
                    ) : analytics.topQueries.slice(0, 5).map((q: any, i: number) => (
                      <div key={i} className="flex justify-between items-center text-xs border-b border-gray-800/20 pb-2">
                        <span className="font-mono text-gray-300 flex items-center gap-1.5">
                          {q.source} <ArrowRight size={10} className="text-gray-500" /> {q.destination}
                        </span>
                        <span className="px-2 py-0.5 bg-indigo-500/10 text-indigo-400 rounded-full font-bold">{q.count} searches</span>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Top Missing Stations */}
                <div className="bg-[#121824] border border-gray-800/80 rounded-xl p-5">
                  <h3 className="text-sm font-semibold text-white mb-3">Top Missing Stations</h3>
                  <div className="space-y-3.5">
                    {(!analytics?.topStations || analytics.topStations.length === 0) ? (
                      <p className="text-xs text-gray-400 text-center py-4">No station query logs available</p>
                    ) : analytics.topStations.slice(0, 5).map((s: any, i: number) => (
                      <div key={i} className="flex justify-between items-center text-xs border-b border-gray-800/20 pb-2">
                        <span className="text-gray-300 font-mono">"{s.query}"</span>
                        <span className="px-2 py-0.5 bg-pink-500/10 text-pink-400 rounded-full font-bold">{s.count} fails</span>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Top Missing Trains */}
                <div className="bg-[#121824] border border-gray-800/80 rounded-xl p-5">
                  <h3 className="text-sm font-semibold text-white mb-3">Top Missing Trains</h3>
                  <div className="space-y-3.5">
                    {(!analytics?.topTrains || analytics.topTrains.length === 0) ? (
                      <p className="text-xs text-gray-400 text-center py-4">No train query logs available</p>
                    ) : analytics.topTrains.slice(0, 5).map((t: any, i: number) => (
                      <div key={i} className="flex justify-between items-center text-xs border-b border-gray-800/20 pb-2">
                        <span className="text-gray-300 font-mono">Train #{t.train_no}</span>
                        <span className="px-2 py-0.5 bg-emerald-500/10 text-emerald-400 rounded-full font-bold">{t.count} fails</span>
                      </div>
                    ))}
                  </div>
                </div>

              </div>
            </div>
          ) : filteredData.length === 0 ? (
            <div className="space-y-4">
              {activeTab === "gpt" && (
                <div className="flex gap-2 mb-4 bg-[#121824] p-1.5 rounded-lg w-fit border border-gray-800/60 animate-fade-in">
                  {(["all", "pending", "approved", "rejected"] as const).map((filter) => (
                    <button
                      key={filter}
                      onClick={() => setGptFilter(filter)}
                      className={`px-3 py-1 text-[11px] font-semibold rounded-md transition duration-150 uppercase ${
                        gptFilter === filter
                          ? "bg-[#6366f1] text-white shadow font-bold"
                          : "text-gray-400 hover:text-gray-200 hover:bg-[#151d2d]"
                      }`}
                    >
                      {filter}
                    </button>
                  ))}
                </div>
              )}
              {activeTab === "routes" && (
                <div className="flex flex-wrap gap-2 mb-4 bg-[#121824] p-1.5 rounded-lg w-fit border border-gray-800/60 animate-fade-in">
                  {([
                    { id: "all", label: "All Routes" },
                    { id: "current_miss", label: "Current Miss" },
                    { id: "resolved", label: "Resolved" },
                    { id: "historical", label: "Historical" },
                    { id: "stale", label: "Stale" },
                    { id: "search", label: "Search Miss" }
                  ] as const).map(({ id, label }) => (
                    <button
                      key={id}
                      onClick={() => setRouteFilter(id as RouteFilterType)}
                      className={`px-3 py-1 text-[11px] font-semibold rounded-md transition duration-150 uppercase ${
                        routeFilter === id
                          ? "bg-pink-600 text-white shadow font-bold"
                          : "text-gray-400 hover:text-gray-200 hover:bg-[#151d2d]"
                      }`}
                    >
                      {label}
                    </button>
                  ))}
                </div>
              )}
              <div className="text-center p-16 text-gray-400 text-sm border border-dashed border-gray-800/60 rounded-xl">
                No {activeTab === "gpt" ? gptFilter : activeTab === "routes" ? routeFilter : ""} logs found in this tab.
              </div>
            </div>
          ) : (
            /* MAIN TABLES */
            <div className="space-y-4">
              {activeTab === "gpt" && (
                <div className="flex gap-2 mb-2 bg-[#121824] p-1.5 rounded-lg w-fit border border-gray-800/60">
                  {(["all", "pending", "approved", "rejected"] as const).map((filter) => (
                    <button
                      key={filter}
                      onClick={() => setGptFilter(filter)}
                      className={`px-3 py-1 text-[11px] font-semibold rounded-md transition duration-150 uppercase ${
                        gptFilter === filter
                          ? "bg-[#6366f1] text-white shadow font-bold"
                          : "text-gray-400 hover:text-gray-200 hover:bg-[#151d2d]"
                      }`}
                    >
                      {filter}
                    </button>
                  ))}
                </div>
              )}
              {activeTab === "routes" && (
                <div className="flex flex-wrap gap-2 mb-2 bg-[#121824] p-1.5 rounded-lg w-fit border border-gray-800/60">
                  {([
                    { id: "all", label: "All Routes" },
                    { id: "current_miss", label: "Current Miss" },
                    { id: "resolved", label: "Resolved" },
                    { id: "historical", label: "Historical" },
                    { id: "stale", label: "Stale" },
                    { id: "search", label: "Search Miss" }
                  ] as const).map(({ id, label }) => (
                    <button
                      key={id}
                      onClick={() => setRouteFilter(id as RouteFilterType)}
                      className={`px-3 py-1 text-[11px] font-semibold rounded-md transition duration-150 uppercase ${
                        routeFilter === id
                          ? "bg-pink-600 text-white shadow font-bold"
                          : "text-gray-400 hover:text-gray-200 hover:bg-[#151d2d]"
                      }`}
                    >
                      {label}
                    </button>
                  ))}
                </div>
              )}
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs border-collapse">
                  <thead>
                    <tr className="text-gray-400 border-b border-gray-800/60 font-semibold">
                      <th className="pb-3 pr-4">Details</th>
                      {activeTab === "queries" && <th className="pb-3 pr-4">Search Date</th>}
                      {activeTab === "routes" && <th className="pb-3 pr-4">Category</th>}
                      {activeTab === "routes" && <th className="pb-3 pr-4">Current State</th>}
                      {activeTab === "routes" && <th className="pb-3 pr-4">Direct Trains</th>}
                      {activeTab === "routes" && <th className="pb-3 pr-4">Valid Splits</th>}
                      {activeTab === "routes" && <th className="pb-3 pr-4">Rejection Diagnostic</th>}
                      {activeTab === "routes" && <th className="pb-3 pr-4">Last Verified</th>}
                      <th className="pb-3 pr-4">Occurrences</th>
                      <th className="pb-3 pr-4">Last seen</th>
                      {activeTab === "gpt" && <th className="pb-3 pr-4">GPT Suggestions</th>}
                      <th className="pb-3 pr-4">Status</th>
                      <th className="pb-3 text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-800/50">
                    {filteredData.map((row) => (
                      <tr key={row.id} className="hover:bg-[#121824]/40 transition duration-150">
                        <td className="py-3.5 pr-4 font-medium text-white">
                          {activeTab === "queries" || activeTab === "routes" || activeTab === "gpt" ? (
                            <div className="flex items-center gap-1.5 font-mono">
                              <span className="text-indigo-400">{row.source}</span>
                              <ArrowRight size={10} className="text-gray-500" />
                              <span className="text-indigo-400">{row.destination}</span>
                            </div>
                          ) : activeTab === "stations" ? (
                            <span className="font-mono text-pink-400">"{row.query}"</span>
                          ) : (
                            <span className="font-mono text-emerald-400">Train #{row.train_no}</span>
                          )}
                        </td>
                        {activeTab === "queries" && (
                          <td className="py-3.5 pr-4 text-gray-300 font-mono text-[11px]">
                            {row.date || "N/A"}
                          </td>
                        )}
                        {activeTab === "routes" && (
                          <td className="py-3.5 pr-4">
                            <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${
                              row.category === "SEARCH_ROUTE_MISS"
                                ? "bg-amber-500/10 text-amber-400 border border-amber-500/20"
                                : "bg-pink-500/10 text-pink-400 border border-pink-500/20"
                            }`}>
                              {row.category === "SEARCH_ROUTE_MISS" ? "SEARCH MISS" : "SPLIT MISS"}
                            </span>
                          </td>
                        )}
                        {activeTab === "routes" && (
                          <td className="py-3.5 pr-4">
                            <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${
                              row.current_state === "RESOLVED"
                                ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20"
                                : row.current_state === "CURRENT_MISS"
                                ? "bg-rose-500/10 text-rose-400 border border-rose-500/20"
                                : row.current_state === "STALE"
                                ? "bg-amber-500/10 text-amber-400 border border-amber-500/20"
                                : "bg-slate-500/10 text-slate-400 border border-slate-500/20"
                            }`}>
                              {row.current_state === "HISTORICAL_MISS" || !row.current_state ? "HISTORICAL" : row.current_state.replace('_', ' ')}
                            </span>
                          </td>
                        )}
                        {activeTab === "routes" && (
                          <td className="py-3.5 pr-4 text-gray-300 font-mono text-[11px]">
                            {row.direct_count != null ? (
                              `${row.direct_count} direct`
                            ) : (
                              <span className="text-gray-500 italic">NOT_REVALIDATED</span>
                            )}
                          </td>
                        )}
                        {activeTab === "routes" && (
                          <td className="py-3.5 pr-4 text-gray-300 font-mono text-[11px]">
                            {row.valid_split_count != null ? (
                              <span className={row.valid_split_count > 0 ? "text-emerald-400 font-bold" : "text-gray-400"}>
                                {row.valid_split_count} splits
                              </span>
                            ) : (
                              <span className="text-gray-500 italic">--</span>
                            )}
                          </td>
                        )}
                        {activeTab === "routes" && (
                          <td className="py-3.5 pr-4">
                            {row.current_state === "RESOLVED" ? (
                              <span className="text-emerald-400 text-[10px] font-medium">None (Valid Splits)</span>
                            ) : row.top_rejection_reason && row.top_rejection_reason !== "NOT_REVALIDATED" ? (
                              <div className="flex flex-wrap gap-1 items-center max-w-xs">
                                <span className="px-1.5 py-0.5 bg-red-500/10 text-red-300 border border-red-500/20 rounded font-mono text-[10px]">
                                  {row.top_rejection_reason}
                                </span>
                                {row.rejection_reasons?.filter((r: string) => r !== row.top_rejection_reason).slice(0, 2).map((r: string, idx: number) => (
                                  <span key={idx} className="px-1.5 py-0.5 bg-gray-800/80 text-gray-400 rounded text-[9px] font-mono">
                                    {r}
                                  </span>
                                ))}
                              </div>
                            ) : (
                              <span className="text-gray-500 italic text-[10px]">NOT_REVALIDATED</span>
                            )}
                          </td>
                        )}
                        {activeTab === "routes" && (
                          <td className="py-3.5 pr-4 text-gray-400 text-[11px]">
                            {row.last_verified_at ? (
                              new Date(row.last_verified_at).toLocaleString()
                            ) : (
                              <span className="text-gray-500 italic">Never</span>
                            )}
                          </td>
                        )}
                        <td className="py-3.5 pr-4">
                          <span className="px-2 py-0.5 bg-gray-800/80 rounded-full font-bold text-gray-300">
                            {row.count}
                          </span>
                        </td>
                        <td className="py-3.5 pr-4 text-gray-400 text-[11px]">
                          {new Date(row.last_seen).toLocaleString()}
                        </td>
                        
                        {/* GPT suggestions column */}
                        {activeTab === "gpt" && (
                          <td className="py-3.5 pr-4 text-gray-300 max-w-sm">
                            {row.gpt_suggestion ? (
                              <div className="bg-[#121824] border border-gray-800 rounded-lg p-3 space-y-1.5">
                                <div className="flex justify-between text-[10px]">
                                  <span className="text-emerald-400 font-mono">Route: {row.gpt_suggestion.candidateRoute}</span>
                                  <span className="px-1.5 py-0.2 bg-[#6366f1]/20 text-[#818cf8] font-bold rounded">
                                    {row.gpt_suggestion.confidence} Confidence
                                  </span>
                                </div>
                                {row.gpt_suggestion.trainNos && (
                                  <p className="text-[10px] text-gray-400">Trains: {row.gpt_suggestion.trainNos.join(", ")}</p>
                                )}
                                <p className="text-[10px] text-gray-400 leading-normal italic">
                                  "{row.gpt_suggestion.reason}"
                                </p>
                              </div>
                            ) : (
                              <span className="text-gray-500">None</span>
                            )}
                          </td>
                        )}

                        <td className="py-3.5 pr-4">
                          <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${
                            row.status === "approved" ? "bg-emerald-500/10 text-emerald-400" :
                            row.status === "rejected" ? "bg-red-500/10 text-red-400" :
                            "bg-yellow-500/10 text-yellow-400"
                          }`}>
                            {row.status}
                          </span>
                        </td>
                        <td className="py-3.5 text-right whitespace-nowrap">
                          <div className="inline-flex gap-2">
                            {activeTab === "routes" && (
                              <button
                                disabled={revalidatingId === row.id}
                                onClick={() => handleRevalidate(row.id, row.source, row.destination, row.date)}
                                className="p-1.5 bg-indigo-600/15 hover:bg-indigo-600/30 text-indigo-400 rounded-lg border border-indigo-500/20 transition flex items-center gap-1 text-[11px]"
                                title="Re-run Split Diagnostic"
                              >
                                {revalidatingId === row.id ? (
                                  <Loader2 size={12} className="animate-spin text-indigo-400" />
                                ) : (
                                  <RefreshCw size={12} />
                                )}
                                Re-run
                              </button>
                            )}
                            {row.status === "pending" && (
                              <>
                                <button
                                  disabled={actioningId === row.id}
                                  onClick={() => handleAction(activeTab, row.id, "approve")}
                                  className="p-1.5 bg-emerald-600/15 hover:bg-emerald-600/30 text-emerald-400 rounded-lg border border-emerald-500/20 transition flex items-center gap-1 text-[11px]"
                                >
                                  <Check size={12} /> Approve
                                </button>
                                <button
                                  disabled={actioningId === row.id}
                                  onClick={() => handleAction(activeTab, row.id, "reject")}
                                  className="p-1.5 bg-red-600/15 hover:bg-red-600/30 text-red-400 rounded-lg border border-red-500/20 transition flex items-center gap-1 text-[11px]"
                                >
                                  <X size={12} /> Reject
                                </button>
                              </>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
